/* LightSpeedUI Level 2 (@lsui/liftoff) — shared visual styles for core UI wrappers.
 * Semantic tokens only; no hex values, Tailwind utilities or CSS Modules.
 */

@layer lsui {
  @layer components {
    [data-lsui-card] {
      box-sizing: border-box;
      padding: var(--space-lg);
      border: var(--border-width) solid var(--color-border);
      border-radius: var(--radius-lg);
      background: var(--color-surface);
      color: var(--color-text);
    }

    [data-lsui-badge] {
      display: inline-flex;
      align-items: center;
      box-sizing: border-box;
      min-block-size: var(--target-min-size, 1.5rem);
      padding-inline: var(--space-2);
      border: var(--border-width) solid var(--color-border);
      border-radius: var(--radius-md);
      background: var(--color-surface-muted, var(--color-surface));
      color: var(--color-text-muted);
      font-family: var(--font-body);
      font-size: var(--text-xs, var(--text-sm));
      font-weight: var(--weight-medium);
    }

    [data-lsui-field] {
      display: grid;
      gap: var(--space-1);
      margin-block-end: var(--space-md);
      color: var(--color-text);
      font-family: var(--font-body);
      font-size: var(--text-sm);
    }

    [data-lsui-field] label {
      font-weight: var(--weight-medium);
    }

    [data-lsui-field] :is(input, select) {
      box-sizing: border-box;
      min-block-size: max(var(--control-height-md), var(--target-min-size, 1.5rem));
      padding: var(--space-2) var(--control-pad-inline-md);
      border: var(--border-width) solid var(--color-border-strong);
      border-radius: var(--radius-md);
      background: var(--color-surface);
      color: var(--color-text);
      font: inherit;
    }

    [data-lsui-field] :is(input, select):focus-visible {
      outline: var(--border-width-lg, 2px) solid var(--color-ring);
      outline-offset: var(--space-1);
    }

    [data-lsui-field] p {
      margin: 0;
      color: var(--color-text-muted);
      font-size: var(--text-xs, var(--text-sm));
    }

    [data-lsui-tabs] [role="tablist"] {
      display: flex;
      gap: var(--space-2);
      border-block-end: var(--border-width) solid var(--color-border);
    }

    [data-lsui-tabs] [role="tab"] {
      min-block-size: var(--target-min-size, 1.5rem);
      padding: var(--space-2) var(--space-3);
      border: 0;
      border-block-end: var(--border-width-lg, 2px) solid transparent;
      background: transparent;
      color: var(--color-text-muted);
      font: inherit;
      cursor: pointer;
    }

    [data-lsui-tabs] [role="tab"][aria-selected="true"] {
      border-block-end-color: var(--color-ring);
      color: var(--color-text);
      font-weight: var(--weight-medium);
    }

    [data-lsui-tabs] [role="tabpanel"] {
      padding-block: var(--space-md);
    }

    [data-lsui-dialog] {
      max-inline-size: min(90vw, 40rem);
      padding: var(--space-lg);
      border: var(--border-width) solid var(--color-border);
      border-radius: var(--radius-lg);
      background: var(--color-surface);
      color: var(--color-text);
    }

    [data-lsui-dialog]::backdrop {
      background: color-mix(in oklab, var(--color-text) 40%, transparent);
    }

    [data-lsui-popover] {
      max-inline-size: min(90vw, 24rem);
      padding: var(--space-md);
      border: var(--border-width) solid var(--color-border);
      border-radius: var(--radius-md);
      background: var(--color-surface);
      color: var(--color-text);
      box-shadow: var(--shadow-md);
    }

    @supports (position-area: block-end) {
      [data-lsui-popover] {
        inset: auto;
        margin: 0;
        position-area: block-end span-inline-start;
        position-try-fallbacks: flip-block, flip-inline, flip-block flip-inline;
      }
    }
  }
}
